func (m *pageMap) reverseIndexBaseName(p *pageState) (string, bool) {
	if p.File() == nil {
		return "", false
	}
	var name string
	if p.File().IsContentAdapter() {
		// Pages created by a content adapter share the adapter file, so use
		// the page's own path to determine its base name.
		name = p.PathInfo().BaseNameNoIdentifier()
	} else {
		name = p.File().FileInfo().Meta().PathInfo.BaseNameNoIdentifier()
	}
	return m.finalizeIndexedBaseName(name), true
}

